#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

int main() {
    long long n;
    long long target;
    cin >> n >> target;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];

    sort(a.begin(), a.end());
    long long count = 0;
    for (int i = 0; i + 3 < n; i++) {
        if (i > 0 && a[i] == a[i - 1]) continue;
        for (int j = i + 1; j + 2 < n; j++) {
            if (j > i + 1 && a[j] == a[j - 1]) continue;
            int l = j + 1, rr = n - 1;
            while (l < rr) {
                long long s = a[i] + a[j] + a[l] + a[rr];
                if (s < target) l++;
                else if (s > target) rr--;
                else {
                    count++;
                    l++;
                    rr--;
                    while (l < rr && a[l] == a[l - 1]) l++;
                }
            }
        }
    }
    cout << count << "\n";

    return 0;
}

